BEGIN
    DECLARE queryVar TEXT;

    -- Construct the dynamic SQL query
    SET queryVar = CONCAT(
        'SELECT SUM(amount) FROM (',
        'SELECT DISTINCT order_id, order_number, amount, customer_name, file_path ',
        'FROM commissions.master_pay_file WHERE file_path LIKE '%', fileName, '%'',
        ') AS distinct_records'
    );
set @query = queryVar;
    -- Prepare and execute the query
    PREPARE stmt FROM @query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END

BEGIN
    DECLARE cur_done INT DEFAULT FALSE;

    -- Variables
    DECLARE v_id VARCHAR(50);
    DECLARE v_owner_id VARCHAR(50);
    DECLARE v_activity_date DATE;

    DECLARE v_employee_id VARCHAR(50) DEFAULT NULL;
    DECLARE v_empalign_ref_id VARCHAR(50) DEFAULT NULL;
    DECLARE v_dept_code VARCHAR(50) DEFAULT NULL;
    DECLARE v_markalign_ref_id VARCHAR(50) DEFAULT NULL;
    DECLARE v_reg_code VARCHAR(50) DEFAULT NULL;
    DECLARE v_regalign_ref_id VARCHAR(50) DEFAULT NULL;
    DECLARE v_div_code VARCHAR(50) DEFAULT NULL;
    DECLARE v_divalign_ref_id VARCHAR(50) DEFAULT NULL;

    -- Cursor
    DECLARE engagement_cursor CURSOR FOR
        SELECT db_id, owner_id, activity_date, empalign_ref_id, markalign_ref_id, regalign_ref_id, divalign_ref_id 
        FROM mdu_engagement
        WHERE empalign_ref_id IS NULL
           OR markalign_ref_id IS NULL
           OR regalign_ref_id IS NULL
           OR divalign_ref_id IS NULL;

    -- Cursor-specific NOT FOUND handler
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET cur_done = TRUE;

    OPEN engagement_cursor;

    read_loop: LOOP
        FETCH engagement_cursor INTO v_id, v_owner_id, v_activity_date, v_empalign_ref_id, v_markalign_ref_id, v_regalign_ref_id, v_divalign_ref_id;
        IF cur_done THEN
            LEAVE read_loop;
        END IF;

        -- Step 0: Get employee_id if empalign is missing
        IF v_empalign_ref_id IS NULL THEN
            IF EXISTS (
                SELECT 1 FROM airtable.align_employee_alignment
                WHERE crm_id = v_owner_id
            ) THEN
                SELECT employee_id INTO v_employee_id
                FROM airtable.align_employee_alignment
                WHERE crm_id = v_owner_id
                LIMIT 1;
            END IF;

            IF v_employee_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM airtable.align_employee_alignment
                WHERE employee_id = v_employee_id
                  AND v_activity_date BETWEEN start_date AND check_date
            ) THEN
                SELECT db_id, dept_code
                INTO v_empalign_ref_id, v_dept_code
                FROM airtable.align_employee_alignment
                WHERE employee_id = v_employee_id
                  AND v_activity_date BETWEEN start_date AND check_date
                LIMIT 1;
            END IF;
        ELSE
            IF EXISTS (
                SELECT 1 FROM airtable.align_employee_alignment
                WHERE db_id = v_empalign_ref_id
            ) THEN
                SELECT dept_code INTO v_dept_code
                FROM airtable.align_employee_alignment
                WHERE db_id = v_empalign_ref_id
                LIMIT 1;
            END IF;
        END IF;

        -- Step 1: markalign

            IF EXISTS (
                SELECT 1 FROM airtable.align_market_alignment
                WHERE dept_code = v_dept_code
                  AND v_activity_date BETWEEN start_date AND check_date
            ) THEN
                SELECT db_id, assigned_to_region_code
                INTO v_markalign_ref_id, v_reg_code
                FROM airtable.align_market_alignment
                WHERE dept_code = v_dept_code
                  AND v_activity_date BETWEEN start_date AND check_date
                LIMIT 1;
            END IF;


        -- Step 2: regalign

            IF EXISTS (
                SELECT 1 FROM airtable.align_region_alignment
                WHERE region_code = v_reg_code
                  AND v_activity_date BETWEEN start_date AND check_date
            ) THEN
                SELECT db_id, assigned_to_division_code
                INTO v_regalign_ref_id, v_div_code
                FROM airtable.align_region_alignment
                WHERE region_code = v_reg_code
                  AND v_activity_date BETWEEN start_date AND check_date
                LIMIT 1;
            END IF;



        -- Step 3: divalign

            IF EXISTS (
                SELECT 1 FROM airtable.align_division_alignment
                WHERE division_code = v_div_code
                  AND v_activity_date BETWEEN start_date AND check_date
            ) THEN
                SELECT db_id
                INTO v_divalign_ref_id
                FROM airtable.align_division_alignment
                WHERE division_code = v_div_code
                  AND v_activity_date BETWEEN start_date AND check_date
                LIMIT 1;
            END IF;


        -- Final update
        UPDATE mdu_engagement
        SET 
            empalign_ref_id = v_empalign_ref_id,
            markalign_ref_id = v_markalign_ref_id,
            regalign_ref_id = v_regalign_ref_id,
            divalign_ref_id = v_divalign_ref_id
        WHERE db_id = v_id;

    END LOOP;

    CLOSE engagement_cursor;
END

