                WHERE division_code = v_div_code
                  AND v_activity_date BETWEEN start_date AND check_date
                LIMIT 1;
            END IF;


        -- Final update
        UPDATE reports.ag_mdu_activity_employee_day
        SET 
            empalign_ref_id = v_empalign_ref_id,
